function englishLayer(unit: HortulanusUnit): CorpusLayer {
  return {
    key: "eng-1597",
    layer: "translation",
    sourceKey: "mirror-alchimy-1597",
    content: unit.text,
    language: "English",
    licence: "public_domain",
    evidence: `${MIRROR_1597_EVIDENCE} (${unit.pages})`,
  };
}

