/** Every passage with text: the base copy and the copy read beside it. */
function witnesses(unit: HortulanusUnit, variantNote?: string) {
  return [
    { manuscriptKey: "huntington-1597", locus: `${unit.pages}; the base copy (EEBO-TCP A01683)` },
    { manuscriptKey: "countway-1597", locus: unit.pages, variantNote },
  ];
}

