const ORDER = ["tablet", "prayer", "preface", ...Array.from({ length: 13 }, (_, i) => String(i + 1))];

function unitKey(unit: string): string {
  return `${PREFIX}.${unit}`;
}

function divisionOf(unit: string): string {
  if (unit === "tablet") return "version";
  if (unit === "prayer" || unit === "preface") return "section";
  return "chapter";
}

function reference(unit: HortulanusUnit): string {
  const n = Number(unit.unit);
  const where = Number.isInteger(n) && n > 0 ? `CHAP. ${NUMERALS[n]}` : unit.unit === "tablet" ? "The Smaragdine Table of Hermes" : unit.unit === "prayer" ? "The praier of Hortulanus" : "The Preface";
  return `${where}; The Mirror of Alchimy (1597), ${unit.pages}`;
}

function buildPassages(): CorpusPassage[] {
  const passages: CorpusPassage[] = [
    {
      key: PREFIX,
      divisionKind: "treatise",
      label: "Hortulanus, commentary on the Emerald Tablet (English of 1597)",
      reference: "A briefe Commentarie of Hortulanus the Philosopher, vpon the Smaragdine Table of Hermes; The Mirror of Alchimy (London, 1597), pp. 16–27",
      sourceKey: "mirror-alchimy-1597",
      summary:
        "A Latin commentary that reads the Emerald Tablet line by line as instructions for making the philosophers' Stone, here in the English printed in The Mirror of Alchimy (1597): the Tablet, Hortulanus's prayer and preface, and thirteen chapters, each explaining one or two lines.",
      notes:
        "The 1597 book prints the same pieces as De Alchemia (Nuremberg, 1541): Bacon's Speculum alchemiae, the Tablet, Hortulanus's commentary and Calid's Book of Secrets; whether its unnamed translator worked from that printing is not shown here. Its title page attributes the book to Roger Bacon; that attribution is doubted and does not cover Hortulanus.",
      verificationStatus: "unverified",
      layers: CITED,
      dates: DATES,
      images: imagesFor(HORTULANUS_IMAGES, PREFIX),
    },
  ];
  for (const id of ORDER) {
    const unit = HORTULANUS_UNITS.find((u) => u.unit === id)!;
    const meta = UNITS[id];
    const key = unitKey(id);
    passages.push({
      key,
      parentKey: PREFIX,
      divisionKind: divisionOf(id),
      label: meta.label,
      reference: reference(unit),
      sourceKey: "mirror-alchimy-1597",
      summary: meta.summary,
      notes: meta.notes,
      verificationStatus: "unverified",
      layers: [englishLayer(unit)],
      witnesses: witnesses(unit, meta.variantNote),
      themes: meta.themes?.map(([themeKey, note]) => ({ themeKey, note })),
      images: imagesFor(HORTULANUS_IMAGES, key),
    });
  }
  return passages;
}

